import React, { useState, useEffect } from 'react';
import './Hero.css';
import Img1 from '../assets/img1.jpg';
import Img2 from '../assets/img2.jpg';
import Img3 from '../assets/img3.jpg';
import Img4 from '../assets/img4.jpeg';
import Img5 from '../assets/img5.jpg';

const Hero = () => {
    // List of your images in public/assets/
    const slides = [

{id:1, url: Img1, title: 'Empowering Rural Communities' },
        { id: 2, url: Img2, title: 'Smart Banking for a Better Future' },
        {id: 3, url: Img3, title: 'Your Trusted Financial Partner' },
{id: 4, url: Img4, title: 'Innovating Financial Solutions' },
{id: 5, url: Img5, title: 'Building a Brighter Tomorrow' },



        // { id: 1, url: '/assets/img1.jpg', title: 'Empowering Rural Communities' },
        // { id: 2, url: '/assets/img2.jpg', title: 'Smart Banking for a Better Future' },
        // { id: 3, url: '/assets/img3.jpg', title: 'Your Trusted Financial Partner' }
    ];

    const [current, setCurrent] = useState(0);

    // Automatic sliding logic
    useEffect(() => {
        const timer = setInterval(() => {
            setCurrent((prev) => (prev === slides.length - 1 ? 0 : prev + 1));
        }, 5000); // Change image every 5 seconds
        return () => clearInterval(timer);
    }, [slides.length]);

    return (
        <section className="hero-container">
            <div className="hero-slider">
                {slides.map((slide, index) => (
                    <div
                        className={index === current ? "slide active" : "slide"}
                        key={slide.id}
                        style={{ backgroundImage: `url(${slide.url})` }}
                    >
                        <div className="hero-overlay">
                            <div className="hero-content">
                                <h1>{slide.title}</h1>
                                <p>Infinity Laghubitta Bittiya Sanstha Limited</p>
                                <button className="hero-cta">Learn More</button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
            
            {/* Optional: Navigation Dots */}
            <div className="slider-dots">
                {slides.map((_, index) => (
                    <span 
                        key={index} 
                        className={index === current ? "dot active" : "dot"}
                        onClick={() => setCurrent(index)}
                    ></span>
                ))}
            </div>
        </section>
    );
};

export default Hero;
